-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.retail.demonhunter.devourer.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.demonhunter.devourer.Description"] = "Empfohlen für Verschlinger. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder Leerenstrahl kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Leerenmetamorphose, Die Jagd und Leerenklinge im Kampf, sobald sie bereit sind, Unterbrechen bei einem unterbrechbaren Zauber und Verschwimmen, wann immer es im Kampf bereit ist. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Unterbrechen nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Verschwimmen Ihnen überlassen."
L["rm.retail.demonhunter.devourer.guide.Name"] = "Referenz (Icy Veins)"
L["rm.retail.demonhunter.devourer.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Vernichter-Priorität von Icy Veins. Die meisten Ihrer Stärkungszauber sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen; Furor ist unter Retail verborgen, daher wartet Leerenstrahl nur auf seine Kosten. Außerhalb von Leerenmetamorphose: Verzehren bei Seelenexplosion, Ernten, Seelenimmolation, wenn sie nicht aktiv ist, Leerenklinge und Die Jagd, sobald Leerenmetamorphose bereit ist, Leerenmetamorphose, Hungernder Hieb, Leerenstrahl, Verzehren. Währenddessen: Verschlingen bei Seelenexplosion, Leerenstrahl, die Stöße der Leerenvernarbten, falls Sie sie haben, Kollabierender Stern, Ausmerzen, Verschlingen, Seelenimmolation. Rotation Master kann Seelenfragmente nicht zählen, daher kommen Ernten und Ausmerzen bei Abklingzeit-Ende. Erinnerungen: Unterbrechen und Verschwimmen."
L["rm.retail.demonhunter.devourer.simc.Name"] = "Referenz (SimulationCraft)"
L["rm.retail.demonhunter.devourer.simc.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Vernichter-Liste von SimulationCraft, die in Leerenmetamorphose wechselt, sobald sie bereit ist. Verborgene Kampfdaten verhindern, dass sie im Kampf in Midnight läuft. Außerhalb: Leerenklinge mit Biss des Verschlingers gegen bis zu drei Gegner und bei voll aufgeladener Leerenmetamorphose, Leerenmetamorphose, Verzehren bei Seelenexplosion, Ernten, Leerenstrahl, Seelenimmolation gegen Gruppen, Verzehren. Währenddessen: Verschlingen bei Seelenexplosion gegen ein Ziel, Die Jagd und Leerenklinge mit Biss des Verschlingers, Leerenstrahl gegen Gruppen, Kollabierender Stern, Ausmerzen, Leerenstrahl, Seelenimmolation, Verschlingen. Erinnerungen: Unterbrechen und Verschwimmen."
L["rm.retail.demonhunter.havoc.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.demonhunter.havoc.Description"] = "Empfohlen für Verwüstung. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent des Spiels Ihnen überlässt: Metamorphose und Die Jagd im Kampf, Rachsüchtiger Rückzug, wenn Sie Trägheit oder Exergie haben, Unterbrechen bei einem unterbrechbaren Zauber und Verschwimmen, wann immer es im Kampf bereit ist. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Unterbrechen nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Verschwimmen Ihnen überlassen. Bewegung, Dunkelheit und Schmuckstücke bleiben Ihnen überlassen."
L["rm.retail.demonhunter.havoc.guide.Name"] = "Referenz (Icy Veins, SimulationCraft und Wowhead)"
L["rm.retail.demonhunter.havoc.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Verwüstung. Ihre Procs, Metamorphose und Essenzbruch sind im Kampf in Midnight für Addons verborgen, daher kann diese Liste dort nicht laufen; lesen Sie sie, oder duplizieren Sie sie, um damit zu experimentieren. Furor ist unter Retail verborgen, daher wartet Teufelsklinge nicht auf Platz. Häscher der Aldrachi: Gleve des Reißers, wenn weder Reißender Stoß noch Glevenhagel aktiv ist, Chaosstoß bei Reißendem Stoß. Teufelsgezeichnete: Essenzbruch, Klingentanz und Chaosstoß während Metamorphose. Dann Klingentanz und Chaosstoß während Essenzbruch, Feuerbrandaura bei zwei Aufladungen, Augenstrahl, Teufelsklinge für Trägheit, Essenzbruch, wenn Augenstrahl erst in mehr als 4 Sekunden bereit ist, Klingentanz, Feuerbrandaura gegen zwei Gegner, Chaosstoß, Teufelsklinge, Feuerbrandaura, Gleve werfen, Teufelsrausch. Erinnerungen: Metamorphose, sobald Augenstrahl und Klingentanz verbraucht sind, Die Jagd, Rachsüchtiger Rückzug, dazu Unterbrechen und Verschwimmen."
L["rm.retail.demonhunter.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.demonhunter.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Dämonenjägers meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Dämonenjäger-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.demonhunter.vengeance.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.demonhunter.vengeance.Description"] = "Empfohlen für Rachsucht. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Dämonenstachel, Flammendes Brandmal, Dämonische Verwüstung und Metamorphose im Kampf, sobald sie bereit sind, Unterbrechen bei einem unterbrechbaren Zauber und Verschwimmen, wann immer es im Kampf bereit ist. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Unterbrechen nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Verschwimmen Ihnen überlassen. Infernoeinschlag, Dunkelheit, Spotten und Schmuckstücke bleiben Ihnen überlassen."
L["rm.retail.demonhunter.vengeance.guide.Name"] = "Referenz (Wowhead und Icy Veins)"
L["rm.retail.demonhunter.vengeance.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Wowhead für Rachsucht mit den Heldentalent-Zielen von Icy Veins. Ihre Stärkungszauber sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen; Furor ist unter Retail verborgen, daher warten Verbraucher nur auf ihre Kosten, und Aufbauzauber vermeiden das Überschreiten des Maximums nicht. Häscher der Aldrachi: Gleve des Reißers, Fraktur bei Reißendem Stoß, Seelenspalter bei Glevenhagel. Dann Fraktur bei vollen Aufladungen, Seelenbombe gegen drei oder mehr Gegner, Feuerbrandaura, Zeichen der Flamme, Seelenspalter gegen ein Ziel, Dämonische Verwüstung, Seelenspalter, Fraktur, Teufelsklinge, Gleve werfen. Rotation Master kann Seelenfragmente nicht zählen, daher richtet sich Seelenbombe nach der Anzahl der Gegner. Erinnerungen: Dämonenstachel, wenn der Effekt fehlt, Metamorphose, Flammendes Brandmal, Zeichen der Bosheit, Seelenschnitzer (Infernoeinschlag bei zwei Aufladungen ist deaktiviert), dazu Unterbrechen und Verschwimmen."
L["rm.retail.demonhunter.vengeance.simc.Name"] = "Referenz (SimulationCraft)"
L["rm.retail.demonhunter.vengeance.simc.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Listen von SimulationCraft für Rachsucht. Verborgene Kampfdaten verhindern, dass sie im Kampf in Midnight laufen, und Furor ist unter Retail verborgen, daher entfallen ihre Furor-Schwellen. Häscher der Aldrachi: zuerst Zeichen der Flamme und Feuerbrandaura, Metamorphose, der Zyklus von Gleve des Reißers mit Teufelsklinge, Flammendes Brandmal, Zeichen der Bosheit, Seelenbombe gegen Gruppen, Seelenschnitzer während Flammendem Untergang, dann Fraktur, Seelenspalter, Teufelsklinge, Dämonische Verwüstung. Vernichter: einen bereiten Leerenfall mit Seelenbombe oder Seelenspalter verbrauchen, Fraktur bei zwei Stapeln Leerenfall, Metamorphose, Seelenbombe, Zeichen der Bosheit, Fraktur bei vollen Aufladungen, Feuerbrandaura, Zeichen der Flamme, Fraktur, Seelenspalter, Teufelsklinge, Gleve werfen. Erinnerungen: Dämonenstachel, Unterbrechen, Verschwimmen."
